import{c as e,Q as a,j as s,m as i}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"David Sacks：Fable 5 禁令完整內幕——Anthropic 拒絕國安審查是根因","description":"","frontmatter":{"url":"https://x.com/DavidSacks/status/2065853007619588171","title":"David Sacks：Fable 5 禁令完整內幕——Anthropic 拒絕國安審查是根因","author":"David Sacks","archived":"2026-06-15T00:00:00.000Z","category":"anthropic-news","handle":"@DavidSacks","published":"2026-06-13T00:00:00.000Z","score":"4.9/10","stats":"25221❤ · 3222 retweets","tags":["fable5","anthropic","export-control","david-sacks","ai-policy"],"type":"tweet-thread"},"headers":[],"relativePath":"research/tweets/2026-06-13-@DavidSacks-588171.md","filePath":"research/tweets/2026-06-13-@DavidSacks-588171.md","lastUpdated":1785909234000}'),r={name:"research/tweets/2026-06-13-@DavidSacks-588171.md"};function o(d,t,n,h,c,l){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="david-sacks-fable-5-禁令完整內幕——anthropic-拒絕國安審查是根因-—-davidsacks" tabindex="-1">David Sacks：Fable 5 禁令完整內幕——Anthropic 拒絕國安審查是根因 — @DavidSacks <a class="header-anchor" href="#david-sacks-fable-5-禁令完整內幕——anthropic-拒絕國安審查是根因-—-davidsacks" aria-label="Permalink to &quot;David Sacks：Fable 5 禁令完整內幕——Anthropic 拒絕國安審查是根因 — @DavidSacks&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/DavidSacks/status/2065853007619588171" target="_blank" rel="noreferrer">https://x.com/DavidSacks/status/2065853007619588171</a><strong>類別</strong>：anthropic-news <strong>統計</strong>：25221❤ · 3222 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>I’ve had a number of conversations with folks inside and outside government about the current situation with Anthropic, and here is what I believe to be true:</p><p>— As we know, Anthropic publicly released its Mythos class models earlier this week under the commercial name Fable.</p><p>— Fable is Mythos with guardrails. But if those guardrails fail, then you’ve exposed Mythos and its advanced cyber capabilities to people who shouldn’t have them. (Keep in mind that Anthropic itself widely promoted the idea that Mythos was a cyberweapon and needed to be regulated as such. They asked for government regulation of Mythos and championed the guardrails on Fable. If there is a vulnerability — big or small — it is Anthropic’s responsibility to patch.)</p><p>— A highly credible trusted partner of both Anthropic and the USG who was testing Fable came forward with a jailbreak of those guardrails. The Admin asked Dario to fix the jailbreak or de-deploy the model. Dario refused.</p><p>— In their blog post, Anthropic defended its decision by saying the jailbreak isn’t serious. That is not what the trusted partner and the USG believe; nor is that kind of minimizing language consistent with Anthropic’s brand as the AI safety company. It’s difficult to fathom how they could claim a jailbreak allowing operability of a cyber weapon could be defined as not “serious.”</p><p>— In the past, Anthropic has always said that safety must be top priority and taken super seriously. In this case, Anthropic prioritized the continued offering of the consumer model over safety.</p><p>— In reaction, the Admin issued the export control. The Admin did this reluctantly. It’s been very surprised that Anthropic hasn’t wanted to cooperate with a reasonable safety request (ie fixing the jailbreak issue). Anthropic’s reaction is very much at odds with their branding and ethos as a safe AI research community.</p><p>— The Admin’s hope now is that Anthropic remediates the safety issue, the export control is lifted, and Fable goes back into general release. The Admin wants all of this to happen as soon as possible. It is frankly bewildered that Anthropic hasn’t wanted to comply with safety requests that it previously said were its highest priority.</p><p>— Those trying to misdirect and tie this action to the prior DoW/Anthropic issues are wrong. The Admin values Anthropic’s technical capabilities and feels that this issue, while serious, should be easily resolved. The ball is in Anthropic’s court.</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>3/10</td><td>政策背景資訊，無法直接轉化為 workspace 操作</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>白宮官員視角揭露政策決策鏈，但屬事件報導非新框架</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>政府內部消息來源，但「匿名」可信度有限</td></tr><tr><td>D. 技術深度 (15%)</td><td>5/10</td><td>政策分析為主，技術細節（jailbreak 性質）語焉不詳</td></tr><tr><td>E. 泛化性 (15%)</td><td>4/10</td><td>主要適用於了解 Anthropic/USG 關係背景</td></tr><tr><td><strong>加權總分</strong></td><td><strong>4.9/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip <strong>理由</strong>：政策事件背景，不影響 workspace 技術決策</p>',17)])])}const b=e(r,[["render",o]]);export{u as __pageData,b as default};
